WITH recent_payments AS (SELECT * FROM payments WHERE status = 'REFUNDED'), summary AS (SELECT order_id, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(method))) AS method_values, ROUND((100 * SUM(CASE WHEN method = 'card' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_card FROM recent_payments GROUP BY order_id) SELECT order_id, method_values, pct_card FROM summary ORDER BY order_id DESC LIMIT 3
